/* cppi::3c1cfcfb06507d3cdd9d2b685c3eaf0267c07a4470ff6c0e3172f8c02bc269b8 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-01' and end_date = '2025-04-01')
and start_date = '2025-04-01' and end_date = '2025-04-01'

/* cppi::e1eb22f4fb936ff5dc36aaf3847ecd470fff246532ee8747125bd2b704dcb8ad */
/* QuickSight 501c08ad-86ff-4a4b-a1d9-41481d8f29c6 */
SELECT "node", "hierarchy_level", "hierarchy_type", "node_level", "account", "pool", "portfolio_type", "active_risk_benchmark", "department", "strategy", "program", "sub_program", "model_portfolio", "analytic_name", "analytic_type", "analytic_value", "override_source", "override_value", "scaling_type", "currency", "curve", "curve_type", "tenor", "methodology", "rating", "confidence_level", CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS "business_date"
FROM "AwsDataCatalog"."risk_prod"."rmv_analytics"
WHERE CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) > from_unixtime(cast(substr(cast(1750676427926 as varchar), 1, 10) AS bigint))

